class Solution {
    public String betterCompression(String compressed) {
        long[] counts = new long[26];
        int n = compressed.length();
        int i = 0;
        while (i < n) {
            char ch = compressed.charAt(i++);
            long val = 0;
            while (i < n && Character.isDigit(compressed.charAt(i))) {
                val = val * 10 + (compressed.charAt(i++) - '0');
            }
            counts[ch - 'a'] += val;
        }
        StringBuilder res = new StringBuilder();
        for (int c = 0; c < 26; ++c) {
            if (counts[c] > 0) {
                res.append((char) ('a' + c)).append(counts[c]);
            }
        }
        return res.toString();
    }
}

var betterCompression = function(compressed) {
    const counts = new Array(26).fill(0);
    const n = compressed.length;
    let i = 0;
    while (i < n) {
        const ch = compressed[i++];
        let val = 0;
        while (i < n && compressed[i] >= '0' && compressed[i] <= '9') {
            val = val * 10 + Number(compressed[i++]);
        }
        counts[ch.charCodeAt(0) - 97] += val;
    }
    let res = '';
    for (let c = 0; c < 26; ++c) {
        if (counts[c] > 0) {
            res += String.fromCharCode(97 + c) + counts[c];
        }
    }
    return res;
};
